let raw;
try {
    raw = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;
} catch(e) { return null; }

const plcId = String(raw.plc_id);
const records = raw.data;
if (!Array.isArray(records) || records.length === 0) return null;
const group = records[0].collection_group || '';

const MODE_MAP = {
    0:'비방수 내부', 1:'비방수 프로브(온도)', 2:'비방수 프로브(전류)',
    3:'3ch 온도(서부발전)', 4:'가스센서(O2,CO,H2S)', 5:'다채널 온도(TC,RTD)',
    7:'비접촉 온도센서', 8:'Pulley 진동 프로브', 9:'PULLEY',
    10:'방수 내부', 11:'방수 프로브', 12:'5K 진동 프로브', 13:'5K 방수 내부'
};

const TAG_V1 = {
    1:{n:'temperature'}, 2:{n:'humidity'}, 3:{n:'pressure'},
    4:{n:'battery'}, 5:{n:'prob_temp'},
    6:{n:'accel_rms_x'}, 7:{n:'accel_rms_y'}, 8:{n:'accel_rms_z'},
    9:{n:'velocity_rms'}, 10:{n:'accel_1k5k'},
    11:{n:'vib_peak'}, 12:{n:'harmony_low'}, 13:{n:'harmony_high'},
    14:{n:'gravity_mag'}, 15:{n:'sound_db'}, 16:{n:'sound_peak'},
    17:{n:'rssi'}, 18:{n:'version'}, 19:{n:'mode'},
    20:{n:'battery_low'}
};
const TAG_V2 = {
    1:{n:'temperature'}, 2:{n:'humidity'}, 3:{n:'probe'},
    4:{n:'battery'}, 5:{n:'sound_db'},
    6:{n:'velocity_rms'}, 7:{n:'accel_x'}, 8:{n:'accel_y'}, 9:{n:'accel_z'},
    10:{n:'vib_fft_freq'}, 11:{n:'sound_fft_freq'},
    12:{n:'rssi'}, 13:{n:'version'}, 14:{n:'mode'},
    15:{n:'battery_low'}
};

const tagMap = (plcId === '54') ? TAG_V2 : TAG_V1;
const parsed = {};
records.forEach(r => {
    const info = tagMap[r.tag_id];
    if (!info) return;
    parsed[info.n] = r.v_float ?? r.v_int ?? r.v_bool ?? r.v_text ?? null;
});

const key = `dev_${plcId}`;
let stored = flow.get(key) || {};
if (group === 'ble_env') stored.env = parsed;
if (group === 'ble_vib') stored.vib = parsed;
stored.ts = records[0]?.source_time
    ? new Date(records[0].source_time).toLocaleTimeString('ko-KR',{hour12:false})
    : '--:--:--';
flow.set(key, stored);

const e = stored.env || {};
const v = stored.vib || {};
const ts = stored.ts;
const modeName = MODE_MAP[e.mode] ?? '-';
const ver = (e.version !== undefined) ? `v${e.version}` : '-';

// --- 스타일 ---
const tbl = `style='width:100%;border-collapse:collapse;font-size:13px;'`;
const thS = `style='background:#2a2a2a;color:#ccc;padding:4px 8px;text-align:left;border:1px solid #444;font-weight:normal;font-size:11px;'`;
const tdO = `style='padding:4px 8px;border:1px solid #444;color:#888;font-size:12px;white-space:nowrap;width:60px;text-align:center;'`;
const tdD = `style='padding:4px 8px;border:1px solid #444;font-size:12px;'`;
const tdV = `style='padding:4px 8px;border:1px solid #444;font-weight:bold;font-size:14px;text-align:right;white-space:nowrap;'`;
const tdU = `style='padding:4px 8px;border:1px solid #444;color:#888;font-size:11px;width:50px;'`;
const secH = `style='background:#1a3a4a;color:#7cc;padding:5px 8px;border:1px solid #444;font-weight:bold;font-size:12px;'`;

function val(x, color) {
    if (x === null || x === undefined) return `<span style='color:#555;'>-</span>`;
    const c = color || '#eee';
    return `<span style='color:${c};'>${x}</span>`;
}

// --- 공통: 기본 데이터 (offset 2~9) ---
function buildCommon() {
    let h = `<tr><td colspan='4' ${secH}>PTS-2305BP 기본 데이터</td></tr>`;
    h += `<tr><td ${thS}>Offset</td><td ${thS}>Description</td><td ${thS}>Value</td><td ${thS}>Unit</td></tr>`;
    h += `<tr><td ${tdO}>2~3</td><td ${tdD}>센서 온도 (Little Endian, /100)</td><td ${tdV}>${val(e.temperature,'#ff8c00')}</td><td ${tdU}>℃</td></tr>`;
    h += `<tr><td ${tdO}>4~5</td><td ${tdD}>센서 습도 (Little Endian, /100)</td><td ${tdV}>${val(e.humidity,'#4fc3f7')}</td><td ${tdU}>%</td></tr>`;
    h += `<tr><td ${tdO}>6~7</td><td ${tdD}>센서 기압 ((raw*255+50000)/4096)</td><td ${tdV}>${val(e.pressure)}</td><td ${tdU}>hPa</td></tr>`;
    h += `<tr><td ${tdO}>8</td><td ${tdD}>배터리 잔량</td><td ${tdV}>${val(e.battery, (e.battery??0)<20?'#ca3838':'#4caf50')}</td><td ${tdU}>%</td></tr>`;
    h += `<tr><td ${tdO}>9</td><td ${tdD}>Mode: <b>${modeName}</b> / FW: ${ver}</td><td ${tdV}>${val(e.mode)}<span style='color:#888;font-size:11px;'> / ${val(e.version)}</span></td><td ${tdU}>-</td></tr>`;
    h += `<tr><td ${tdO}>-</td><td ${tdD}>RSSI</td><td ${tdV}>${val(e.rssi)}</td><td ${tdU}>dBm</td></tr>`;
    return h;
}

// Output: [0] dev2_detail, [1] dev3_detail, [2] dev4_detail,
//         [3] dev2_gauges(5), [4..8] g2_ax,ay,az,vel,a15k
//         [9] dev3_gauges(4), [10..13] g3_temp,probe,humi,batt
//         [14] dev4_gauges(4), [15..18] g4_temp,humi,probe,batt
//         [19] chart_temp, [20] chart_vib, [21] chart_probe
const out = new Array(22).fill(null);

// ===== #2 Pulley 진동 프로브 =====
if (plcId === '52') {
    let html = `<table ${tbl}>`;
    html += buildCommon();
    html += `<tr><td colspan='4' ${secH}>진동 데이터 (Offset 10~28)</td></tr>`;
    html += `<tr><td ${thS}>Offset</td><td ${thS}>Description</td><td ${thS}>Value</td><td ${thS}>Unit</td></tr>`;
    html += `<tr><td ${tdO}>10~11</td><td ${tdD}>X축 가속도 합산 RMS (Big Endian, /100)</td><td ${tdV}>${val(v.accel_rms_x,'#ef5350')}</td><td ${tdU}>m/s²</td></tr>`;
    html += `<tr><td ${tdO}>12~13</td><td ${tdD}>Y축 가속도 합산 RMS (Big Endian, /100)</td><td ${tdV}>${val(v.accel_rms_y,'#42a5f5')}</td><td ${tdU}>m/s²</td></tr>`;
    html += `<tr><td ${tdO}>14~15</td><td ${tdD}>Z축 가속도 합산 RMS (Big Endian, /100)</td><td ${tdV}>${val(v.accel_rms_z,'#66bb6a')}</td><td ${tdU}>m/s²</td></tr>`;
    html += `<tr><td ${tdO}>16~17</td><td ${tdD}>1000Hz 이하 속도 RMS (Little Endian, /100)</td><td ${tdV}>${val(v.velocity_rms,'#ffa726')}</td><td ${tdU}>mm/s</td></tr>`;
    html += `<tr><td ${tdO}>18~19</td><td ${tdD}>1kHz~5kHz 가속도 RMS (Big Endian, /100)</td><td ${tdV}>${val(v.accel_1k5k,'#ab47bc')}</td><td ${tdU}>m/s²</td></tr>`;
    html += `<tr><td ${tdO}>20~21</td><td ${tdD}>진동 FFT 주파수 Peak (Big Endian)</td><td ${tdV}>${val(v.vib_peak)}</td><td ${tdU}>Hz</td></tr>`;
    html += `<tr><td ${tdO}>22</td><td ${tdD}>고조파 성분 ~1kHz 발생건</td><td ${tdV}>${val(v.harmony_low)}</td><td ${tdU}>count</td></tr>`;
    html += `<tr><td ${tdO}>23</td><td ${tdD}>고조파 성분 1k~5kHz 발생건</td><td ${tdV}>${val(v.harmony_high)}</td><td ${tdU}>count</td></tr>`;
    html += `<tr><td ${tdO}>24~25</td><td ${tdD}>x,y,z 중력가속도 Magnitude (Big Endian)</td><td ${tdV}>${val(v.gravity_mag)}</td><td ${tdU}>mg</td></tr>`;
    html += `<tr><td ${tdO}>26</td><td ${tdD}>Sound dB</td><td ${tdV}>${val(v.sound_db)}</td><td ${tdU}>dB</td></tr>`;
    html += `<tr><td ${tdO}>27~28</td><td ${tdD}>Sound FFT 주파수 Peak (Big Endian)</td><td ${tdV}>${val(v.sound_peak)}</td><td ${tdU}>Hz</td></tr>`;
    html += `<tr><td colspan='4' style='padding:3px 8px;color:#555;font-size:10px;text-align:right;border:1px solid #444;'>Updated: ${ts}</td></tr>`;
    html += `</table>`;
    out[0] = {payload: html};

    // 도넛 게이지
    if (v.accel_rms_x !== undefined) out[4] = {payload: v.accel_rms_x};
    if (v.accel_rms_y !== undefined) out[5] = {payload: v.accel_rms_y};
    if (v.accel_rms_z !== undefined) out[6] = {payload: v.accel_rms_z};
    if (v.velocity_rms !== undefined) out[7] = {payload: v.velocity_rms};
    if (v.accel_1k5k !== undefined) out[8] = {payload: v.accel_1k5k};

    if (group === 'ble_env' && e.temperature !== undefined) out[19] = {payload: e.temperature, topic: '#2 (DB:C7)'};
    if (group === 'ble_vib' && v.velocity_rms !== undefined) out[20] = {payload: v.velocity_rms, topic: '#2 VelRMS'};
}

// ===== #3 비접촉 온도센서 =====
if (plcId === '53') {
    let html = `<table ${tbl}>`;
    html += buildCommon();
    html += `<tr><td colspan='4' ${secH}>비접촉 온도 (Offset 29~30)</td></tr>`;
    html += `<tr><td ${thS}>Offset</td><td ${thS}>Description</td><td ${thS}>Value</td><td ${thS}>Unit</td></tr>`;
    html += `<tr><td ${tdO}>29~30</td><td ${tdD}>프로브 온도 (Little Endian, /100)</td><td ${tdV}>${val(e.prob_temp,'#ff5722')}</td><td ${tdU}>℃</td></tr>`;
    html += `<tr><td colspan='4' style='padding:3px 8px;color:#555;font-size:10px;text-align:right;border:1px solid #444;'>Updated: ${ts}</td></tr>`;
    html += `</table>`;
    out[1] = {payload: html};

    // 도넛 게이지
    if (e.temperature !== undefined) out[10] = {payload: e.temperature};
    if (e.prob_temp !== undefined) out[11] = {payload: e.prob_temp};
    if (e.humidity !== undefined) out[12] = {payload: e.humidity};
    if (e.battery !== undefined) out[13] = {payload: e.battery};

    if (group === 'ble_env') {
        if (e.temperature !== undefined) out[19] = {payload: e.temperature, topic: '#3 (EE:12)'};
        if (e.prob_temp !== undefined) out[21] = {payload: e.prob_temp, topic: '#3 Probe'};
    }
}

// ===== #4 V2 =====
if (plcId === '54') {
    let html = `<table ${tbl}>`;
    html += `<tr><td colspan='4' ${secH}>PTS-2305BP V2 데이터</td></tr>`;
    html += `<tr><td ${thS}>Field</td><td ${thS}>Description</td><td ${thS}>Value</td><td ${thS}>Unit</td></tr>`;
    html += `<tr><td ${tdO}>Mode</td><td ${tdD}>${modeName}</td><td ${tdV}>${val(e.mode)}</td><td ${tdU}>-</td></tr>`;
    html += `<tr><td ${tdO}>FW</td><td ${tdD}>Version</td><td ${tdV}>${ver}</td><td ${tdU}>-</td></tr>`;
    html += `<tr><td ${tdO}>온도</td><td ${tdD}>Temperature (Little Endian, /100)</td><td ${tdV}>${val(e.temperature,'#ff8c00')}</td><td ${tdU}>℃</td></tr>`;
    html += `<tr><td ${tdO}>습도</td><td ${tdD}>Humidity (Little Endian, /100)</td><td ${tdV}>${val(e.humidity,'#4fc3f7')}</td><td ${tdU}>%</td></tr>`;
    html += `<tr><td ${tdO}>프로브</td><td ${tdD}>Probe (Little Endian, /100)</td><td ${tdV}>${val(e.probe,'#ff5722')}</td><td ${tdU}>℃</td></tr>`;
    html += `<tr><td ${tdO}>배터리</td><td ${tdD}>Battery</td><td ${tdV}>${val(e.battery,'#4caf50')}</td><td ${tdU}>%</td></tr>`;
    html += `<tr><td ${tdO}>소음</td><td ${tdD}>Sound dB</td><td ${tdV}>${val(v.sound_db)}</td><td ${tdU}>dB</td></tr>`;
    html += `<tr><td ${tdO}>속도</td><td ${tdD}>Velocity RMS</td><td ${tdV}>${val(v.velocity_rms)}</td><td ${tdU}>mm/s</td></tr>`;
    html += `<tr><td ${tdO}>가속도</td><td ${tdD}>X / Y / Z</td><td ${tdV}>${val(v.accel_x)} / ${val(v.accel_y)} / ${val(v.accel_z)}</td><td ${tdU}>mg</td></tr>`;
    html += `<tr><td ${tdO}>FFT</td><td ${tdD}>Vib / Sound</td><td ${tdV}>${val(v.vib_fft_freq)} / ${val(v.sound_fft_freq)}</td><td ${tdU}>Hz</td></tr>`;
    html += `<tr><td ${tdO}>RSSI</td><td ${tdD}>Signal Strength</td><td ${tdV}>${val(e.rssi)}</td><td ${tdU}>dBm</td></tr>`;
    html += `<tr><td colspan='4' style='padding:3px 8px;color:#555;font-size:10px;text-align:right;border:1px solid #444;'>Updated: ${ts}</td></tr>`;
    html += `</table>`;
    out[2] = {payload: html};

    if (e.temperature !== undefined) out[15] = {payload: e.temperature};
    if (e.humidity !== undefined) out[16] = {payload: e.humidity};
    if (e.probe !== undefined) out[17] = {payload: e.probe};
    if (e.battery !== undefined) out[18] = {payload: e.battery};

    if (group === 'ble_env' && e.temperature !== undefined) out[19] = {payload: e.temperature, topic: '#4 V2 (0A:38)'};
}

return out;
